     1	mod assembly_builder;
     2	mod ast_def;
     3	mod ir_builder;
     4	
     5	use koopa::back::KoopaGenerator;
     6	use lalrpop_util::lalrpop_mod;
     7	
     8	// 引用 lalrpop 生成的解析器
     9	// 因为我们刚刚创建了 sysy.lalrpop, 所以模块名是 sysy
    10	lalrpop_mod!(sysy);
    11	
    12	fn main() -> Result<(), Box<dyn std::error::Error>> {
    13	    // Compiler configuration:
    14	    // Set the pointer size in our compiled code to 4. (32 bits)
    15	    koopa::ir::Type::set_ptr_size(4);
    16	
    17	    // 解析命令行参数
    18	    let mut args = std::env::args();
    19	    args.next();
    20	    let mode = args.next().unwrap();
    21	    let input = args.next().unwrap();
    22	    args.next();
    23	    let output = args.next().unwrap();
    24	
    25	    // 读取输入文件
    26	    let input = std::fs::read_to_string(input)?;
    27	
    28	    // 调用 lalrpop 生成的 parser 解析输入文件
    29	    let ast = sysy::CompUnitParser::new()
    30	        .parse(&input)
    31	        .expect("Parse error");
    32	
    33	    // 输出解析得到的 AST
    34	    // dbg!("AST:\n{:#?}", &ast);
    35	
    36	    // Generate in-memory Koopa IR (struct Program) using my IR builder.
    37	    let ir: koopa::ir::Program = ir_builder::generate_ir(&ast)?;
    38	
    39	    match mode.as_str() {
    40	        // Convert in-memory Koopa IR to text, and write it to output file (hello.koopa).
    41	        "-koopa" => {
    42	            let mut text_generator = KoopaGenerator::new(Vec::new());
    43	            text_generator.generate_on(&ir).unwrap();
    44	            std::fs::write(output, text_generator.writer())?;
    45	            Ok(())
    46	        }
    47	        "-riscv" | "-perf" => {
    48	            let mut output_file = std::fs::File::create(output)?;
    49	            assembly_builder::generate_assembly(&ir, &mut output_file)?;
    50	            // for assembly_code in assembly_codes {
    51	            //   writeln!(output_file, "{}", assembly_code)?;
    52	            // }
    53	            Ok(())
    54	        }
    55	        mode => Err(mode),
    56	    }?;
    57	    Ok(())
    58	}
