 14	
 15	use self::build_expressions::{IRExpBuildResult, IRExpBuildable};
 16	
 17	pub fn generate_ir(comp_unit: &CompUnit) -> Result<Program, String> {
 18	    let mut program = Program::new();
 19	    let mut my_ir_generator_info = MyIRGeneratorInfo {
 20	        curr_block: None,
 21	        break_tgt_blocks: vec![],
 22	        continue_tgt_blocks: vec![],
 23	        curr_func: None,
 24	        symbol_tables: SymbolTableStack {
 25	            symbol_tables: vec![HashMap::new()],
 26	        },
 27	        bb_cnt: 0,
 28	        function_table: HashMap::new(),
 29	    };
 30	    comp_unit.build(&mut program, &mut my_ir_generator_info)?;
 31	    Ok(program)
 32	}
 33	
 34	#[derive(Debug)]
 35	pub struct MyIRGeneratorInfo {
 36	    curr_block: Option<BasicBlock>,            // Current block
 37	    break_tgt_blocks: Vec<BasicBlock>,         // Target blocks of break statements
 38	    continue_tgt_blocks: Vec<BasicBlock>,      // Target blocks of continue statements
 39	    curr_func: Option<Function>,               // Current function
 40	    symbol_tables: SymbolTableStack,           // Symbol table: ident-(type, Value)
 41	    bb_cnt: usize,                             // Number of BasicBlocks
 42	    function_table: HashMap<String, Function>, // Function table
 43	}
 44	
 45	impl MyIRGeneratorInfo {
 46	    fn check_duplicate_global_symbol(&self, name: &String) -> bool {
 47	        let result_var = match self.symbol_tables.symbol_tables[0].get(name) {
 48	            Some(s) => match s {
 49	                SymbolTableEntry::Variable(_, _) => true,
 50	                SymbolTableEntry::Constant(_, _) => false,
 51	            },
 52	            None => false,
 53	        };
 54	        let result_func = self.function_table.get(name).is_some();
 55	        result_var || result_func
 56	    }
 57	}
 58	
 59	#[derive(Debug)]
 60	pub struct SymbolTableStack {
 61	    symbol_tables: Vec<HashMap<String, SymbolTableEntry>>, // Symbol table: ident-(type, Value)
 62	}
 63	
 64	impl SymbolTableStack {
 65	    fn get(&self, name: &String) -> Option<&SymbolTableEntry> {
 66	        for table in self.symbol_tables.iter().rev() {
 67	            if let Some(symbol) = table.get(name) {
 68	                return Some(symbol);
 69	            }
 70	        }
 71	        None
 72	    }
 73	    // fn get_nearest(&self, name: &String) -> Option<&SymbolTableEntry> {
 74	
 75	    // }
 76	    fn insert(&mut self, name: String, entry: SymbolTableEntry) {
 77	        let table = self.symbol_tables.last_mut().unwrap();
 78	        table.insert(name, entry);
 79	    }
 80	    fn add_new_table(&mut self) {
 81	        self.symbol_tables.push(HashMap::new());
 82	    }
 83	    fn delete_new_table(&mut self) {
 84	        self.symbol_tables.pop();
 85	    }
 86	    // fn curr_depth(&self) -> usize {
 87	    //     self.symbol_tables.len() - 1
 88	    // }
 89	}
