 96	impl std::fmt::Debug for SymbolTableEntry {
 97	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 98	        match self {
 99	            SymbolTableEntry::Variable(tk, v) => write!(f, "Variable({}): {:?}", tk, v),
100	            SymbolTableEntry::Constant(tk, v) => write!(f, "Constant({}): {:?}", tk, v),
101	        }
102	    }
103	}
