    87	    fn is_temp_value(&self, value: Value) -> bool {
    88	        let value_data = match value.is_global() {
    89	            true => self.program.borrow_value(value).clone(),
    90	            false => self.fd.dfg().value(value).clone(),
    91	        };
    92	        match value_data.name() {
    93	            Some(name) => name.starts_with("%"),
    94	            None => true,
    95	        }
    96	    }
    97	
    98	    fn remove_temp_value(&mut self, value: Value) {
    99	        // assert!(
   100	        //     self.is_temp_value(value),
   101	        //     "Can only remove temp values in table!"
   102	        // );
   103	        if !self.is_temp_value(value) {
   104	            return;
   105	        }
   106	        if let Some(reg) = self.__is_value_in_register(value) {
   107	            self.__free_user(reg);
   108	        }
   109	        self.local_value_location.remove(&value);
   110	    }
