  1	// lalrpop 里的约定
  2	use crate::ast_def::{*, declarations::*, statements::*, expressions::*, symbols::*};
  3	use koopa::ir::types::TypeKind;
  4	grammar;
  5	
  6	// 约束 lexer 的行为
  7	match {
  8	  // 跳过空白符和注释
  9	  r"\s*" => {},
 10	  r"//[^\n\r]*[\n\r]*" => {},
 11	  // 块注释也要跳过——XHZ
 12	  r"\/\*([^*]|(\*+([^*/])))*\*+\/" => {},
 13	  // 剩下的情况采用默认方式处理
 14	  _
 15	}
 16	
 17	// 定义 CompUnit, 其返回值类型为 String
 18	// parser 在解析完成后的行为是返回 FuncDef 的值
 19	pub CompUnit: CompUnit = <cs: (Unit)*> => CompUnit::Default(cs);
 20	
 21	pub Unit: Unit = {
 22	  <d: Decl> => Unit::Decl(d), 
 23	  <f: FuncDef> => Unit::FuncDef(f), 
 24	}
 25	
 26	// ======================================================
 27	// Declarations
 28	// ======================================================
 29	
 30	// 同上, 不解释
 31	FuncDef: FuncDef = {
 32	  <return_type: BType> <func_id: IDENT> "(" <params: (FuncFParams)?> ")" <block: Block> => {
 33	    let mut vec = Vec::<FuncFParam>::new();
 34	    if let Some(ps) = params {
 35	      vec.extend(ps);
 36	    }
 37	    FuncDef::Default(return_type, func_id, vec, block)
 38	  }
 39	}
 40	
 41	FuncFParams: Vec<FuncFParam> = {
 42	  <fp: FuncFParam> <fps: ("," <FuncFParam>)*> => {
 43	    let mut vec = Vec::<FuncFParam>::new();
 44	    vec.push(fp);
 45	    for ffp in fps {
 46	      vec.push(ffp);
 47	    }
 48	    vec
 49	  }
 50	}
 51	
 52	FuncFParam: FuncFParam = {
 53	  <b: BType> <i: IDENT> => FuncFParam::Default(b, i, None),
 54	  <b: BType> <i: IDENT> "[" "]" <indexes: ("[" <Exp> "]")*> => FuncFParam::Default(b, i, Some(indexes)),
 55	}
 56	
 57	FuncRParams: Vec<Exp> = {
 58	  <e: Exp> <es: ("," <Exp>)*> => {
 59	    let mut vec = Vec::<Exp>::new();
 60	    vec.push(e);
 61	    for ee in es {
 62	      vec.push(ee);
 63	    }
 64	    vec
 65	  }
 66	}
 67	
 68	Block: Block = "{" <block_items: (BlockItem)*> "}" => Block::Default(block_items); // Referenced from kira-rs. 
 69	
 70	BlockItem: BlockItem = {
 71	  <decl: Decl> => BlockItem::Decl(decl), 
 72	  <stmt: Stmt> => BlockItem::Stmt(stmt), 
 73	}
 74	
 75	Decl: Decl = {
 76	  <c: ConstDecl> => Decl::ConstDecl(c), 
 77	  <v: VarDecl> => Decl::VarDecl(v), 
 78	}
 79	
 80	ConstDecl: ConstDecl = "const" <b: BType> <c: ConstDef> <cs: ("," <ConstDef>)*> ";" => {
 81	  let mut vec = Vec::<ConstDef>::new();
 82	  vec.push(c);
 83	  for cc in cs {
 84	    vec.push(cc);
 85	  }
 86	  ConstDecl::Default(b, vec)
 87	};
 88	
 89	ConstDef: ConstDef = { 
 90	  <i: IDENT> <shape: ("[" <Exp> "]")*> "=" <c: InitVal> => ConstDef::Default(i, shape, c),
 91	}
 92	
 93	VarDecl: VarDecl = <b: BType> <v: VarDef> <vs: ("," <VarDef>)*> ";" => {
 94	  let mut vec = Vec::<VarDef>::new();
 95	  vec.push(v);
 96	  for vv in vs {
 97	    vec.push(vv);
 98	  }
 99	  VarDecl::Default(b, vec)
100	};
101	
102	VarDef: VarDef = {
103	  <i: IDENT> <shape: ("[" <Exp> "]")*> <val: ("=" <InitVal>)?> => VarDef::Default(i, shape, val), 
104	}
105	
106	InitVal: InitVal = {
107	  <e: Exp> => InitVal::Exp(e),
108	  "{" "}" => InitVal::Aggregate(Vec::<Box<InitVal>>::new()),
109	  "{" <val: InitVal> <vals: ("," <InitVal>)*> "}" => {
110	    let mut vec = Vec::<Box<InitVal>>::new();
111	    vec.push(Box::new(val));
112	    for vall in vals {
113	      vec.push(Box::new(vall));
114	    }
115	    InitVal::Aggregate(vec)
116	  }
117	}
118	
119	// ======================================================
120	// Statements
121	// ======================================================
122	
123	Stmt: Stmt = {
124	  <us: UnmatchedStmt> => Stmt::UnmatchedStmt(us), 
125	  <ms: MatchedStmt> => Stmt::MatchedStmt(ms), 
126	}
127	
128	UnmatchedStmt: UnmatchedStmt = {
129	  "if" "(" <e: Exp> ")" <ms: MatchedStmt>
130	    => UnmatchedStmt{default: BasicStmt::IfStmt(e, Box::new(ms.default), Box::new(None))}, 
131	  "if" "(" <e: Exp> ")" <ums: UnmatchedStmt>
132	    => UnmatchedStmt{default: BasicStmt::IfStmt(e, Box::new(ums.default), Box::new(None))}, 
133	  "if" "(" <e: Exp> ")" <ms: MatchedStmt> "else" <ums: UnmatchedStmt> 
134	    => UnmatchedStmt{default: BasicStmt::IfStmt(e, Box::new(ms.default), Box::new(Some(ums.default)))}, 
135	  "while" "(" <e: Exp> ")" <ums: UnmatchedStmt> 
136	    => UnmatchedStmt{default: BasicStmt::WhileStmt(e, Box::new(ums.default))}, 
137	}
138	
139	MatchedStmt: MatchedStmt =  {
140	  <l: LVal> "=" <e: Exp> ";" => MatchedStmt{default: BasicStmt::AssignStmt(l, e)}, 
141	  <e: (Exp)?> ";" => MatchedStmt{default: BasicStmt::Exp(e)}, 
142	  <b: Block> => MatchedStmt{default: BasicStmt::Block(b)}, 
143	  "if" "(" <e: Exp> ")" <s1: MatchedStmt> "else" <s2: MatchedStmt> 
144	    => MatchedStmt{default: BasicStmt::IfStmt(e, Box::new(s1.default), Box::new(Some(s2.default)))}, 
145	  "while" "(" <e: Exp> ")" <ms: MatchedStmt> 
146	    => MatchedStmt{default: BasicStmt::WhileStmt(e, Box::new(ms.default))}, 
147	  "break" ";" => MatchedStmt{default: BasicStmt::BreakStmt}, 
148	  "continue" ";" => MatchedStmt{default: BasicStmt::ContinueStmt}, 
149	  "return" <e: (Exp)?> ";" => MatchedStmt{default: BasicStmt::ReturnStmt(e)}, 
150	}
151	
152	// ======================================================
153	// Expressions
154	// ======================================================
155	
156	Exp: Exp = {
157	  <lor_exp: LOrExp> => Exp::LOrExp(lor_exp), 
158	}
159	
160	LOrExp: LOrExp = {
161	  <land_exp: LAndExp> => LOrExp::LAndExp(land_exp), 
162	  <lor_exp: LOrExp> "||" <land_exp: LAndExp> => LOrExp::BinaryLOrExp(Box::new(lor_exp), land_exp), 
163	}
164	
165	LAndExp: LAndExp = {
166	  <eq_exp: EqExp> => LAndExp::EqExp(eq_exp), 
167	  <land_exp: LAndExp> "&&" <eq_exp: EqExp> => LAndExp::BinaryLAndExp(Box::new(land_exp), eq_exp), 
168	}
169	
170	EqExp: EqExp = {
171	  <rel_exp: RelExp> => EqExp::RelExp(rel_exp), 
172	  <eq_exp: EqExp> "==" <rel_exp: RelExp> => EqExp::BinaryEqExp(Box::new(eq_exp), rel_exp), 
173	  <eq_exp: EqExp> "!=" <rel_exp: RelExp> => EqExp::BinaryUneqExp(Box::new(eq_exp), rel_exp), 
174	}
175	
176	RelExp: RelExp = {
177	  <add_exp: AddExp> => RelExp::AddExp(add_exp), 
178	  <rel_exp: RelExp> "<" <add_exp: AddExp> => RelExp::BinaryLtExp(Box::new(rel_exp), add_exp), 
179	  <rel_exp: RelExp> ">" <add_exp: AddExp> => RelExp::BinaryGtExp(Box::new(rel_exp), add_exp), 
180	  <rel_exp: RelExp> "<=" <add_exp: AddExp> => RelExp::BinaryLeExp(Box::new(rel_exp), add_exp), 
181	  <rel_exp: RelExp> ">=" <add_exp: AddExp> => RelExp::BinaryGeExp(Box::new(rel_exp), add_exp), 
182	}
183	
184	AddExp: AddExp = {
185	  <mul_exp: MulExp> => AddExp::MulExp(mul_exp), 
186	  <add_exp: AddExp> "+" <mul_exp: MulExp> => AddExp::BinaryAddExp(Box::new(add_exp), mul_exp), 
187	  <add_exp: AddExp> "-" <mul_exp: MulExp> => AddExp::BinarySubExp(Box::new(add_exp), mul_exp), 
188	}
189	
190	MulExp: MulExp = {
191	  <unary_exp: UnaryExp> => MulExp::UnaryExp(unary_exp), 
192	  <mul_exp: MulExp> "*" <unary_exp: UnaryExp> => MulExp::BinaryMulExp(Box::new(mul_exp), unary_exp), 
193	  <mul_exp: MulExp> "/" <unary_exp: UnaryExp> => MulExp::BinaryDivExp(Box::new(mul_exp), unary_exp), 
194	  <mul_exp: MulExp> "%" <unary_exp: UnaryExp> => MulExp::BinaryModExp(Box::new(mul_exp), unary_exp), 
195	}
196	
197	UnaryExp: UnaryExp = {
198	  <primary_exp: PrimaryExp> => UnaryExp::PrimaryExp(primary_exp), 
199	  "+" <unary_exp: UnaryExp> => UnaryExp::PlusUnaryExp(Box::new(unary_exp)), 
200	  "-" <unary_exp: UnaryExp> => UnaryExp::MinusUnaryExp(Box::new(unary_exp)), 
201	  "!" <unary_exp: UnaryExp> => UnaryExp::NotUnaryExp(Box::new(unary_exp)), 
202	  <i: IDENT> "(" <params: (FuncRParams)?> ")" => {
203	    let mut vec = Vec::<Exp>::new();
204	    if let Some(ps) = params {
205	      vec.extend(ps);
206	    }
207	    UnaryExp::FuncCall(i, vec)
208	  }
209	}
210	
211	PrimaryExp: PrimaryExp = {
212	  "(" <exp: Exp> ")" => PrimaryExp::BracedExp(Box::new(exp)), 
213	  <lval: LVal> => PrimaryExp::LVal(lval), 
214	  <number: Number> => PrimaryExp::Number(number), 
215	}
216	
217	LVal: LVal = {
218	  <i: IDENT> <indexes: ("[" <Exp> "]")*> => LVal::Default(i, indexes), 
219	}
220	
221	Number: Number = {
222	  <int_const: INTCONST> => Number::INTCONST(int_const), 
223	}
224	
225	// 对整数字面量的处理方式: 把匹配到的字符串按对应进制转换成数字
226	INTCONST: i32 = {
227	  r"[1-9][0-9]*" => i32::from_str_radix(<>, 10).unwrap(),
228	  r"0[0-7]*" => i32::from_str_radix(<>, 8).unwrap(),
229	  r"0[xX][0-9a-fA-F]+" => i32::from_str_radix(&<>[2..], 16).unwrap(),
230	}
231	
232	//! ======================================================
233	//! Symbols
234	//! ======================================================
235	// 如果匹配到标识符, 就返回这个字符串
236	// 一对尖括号在此处指代的是正则表达式匹配到的字符串 (&str)
237	// 关于尖括号到底代表什么, 请 RTFM
238	IDENT: IDENT = r"[_a-zA-Z][_a-zA-Z0-9]*" => IDENT{content: <>.to_string()};
239	
