241	//   "int" => FuncType{content: TypeKind::Int32}, 
242	//   "void" => FuncType{content: TypeKind::Unit}, 
243	// }
244	
245	BType: BType = {
246	  "int" => BType{content: TypeKind::Int32}, 
247	  "void" => BType{content: TypeKind::Unit}, 
