  1	//! Koopa IR entities, including programs ([`Program`]), functions
  2	//! ([`Function`], [`FunctionData`]), basic blocks ([`BasicBlock`],
  3	//! [`BasicBlockData`]) and values ([`Value`], [`ValueData`]).
  4	
  5	use crate::ir::builder::GlobalBuilder;
  6	use crate::ir::dfg::DataFlowGraph;
  7	use crate::ir::idman::{is_global_id, next_func_id, next_global_value_id};
  8	use crate::ir::idman::{BasicBlockId, FunctionId, ValueId};
  9	use crate::ir::layout::Layout;
 10	use crate::ir::types::Type;
 11	use crate::ir::values;
 12	use std::cell::{Ref, RefCell};
 13	use std::collections::{HashMap, HashSet};
 14	use std::rc::{Rc, Weak};
 15	
 16	/// A Koopa IR program.
 17	///
 18	/// Programs can hold global values and functions.
 19	#[derive(Default)]
 20	pub struct Program {
 21	  pub(in crate::ir) values: Rc<RefCell<HashMap<Value, ValueData>>>,
 22	  pub(in crate::ir) inst_layout: Vec<Value>,
 23	  funcs: HashMap<Function, FunctionData>,
 24	  func_tys: Rc<RefCell<HashMap<Function, Type>>>,
 25	  func_layout: Vec<Function>,
 26	}
 27	
 28	/// Returns a mutable reference to the global value data by the given
 29	/// value handle.
 30	macro_rules! data_mut {
 31	  ($self:ident, $value:expr) => {
 32	    $self
 33	      .values
 34	      .borrow_mut()
 35	      .get_mut(&$value)
 36	      .expect("value does not exist")
 37	  };
 38	}
 39	
 40	impl Program {
 41	  /// Creates a new program.
 42	  pub fn new() -> Self {
 43	    Self::default()
 44	  }
 45	
 46	  /// Creates a new global value in the current program.
 47	  /// Returns a [`GlobalBuilder`] for building the new global value.
 48	  pub fn new_value(&mut self) -> GlobalBuilder {
 49	    GlobalBuilder { program: self }
 50	  }
 51	
 52	  /// Creates a new global value by its value data. Returns the handle of
 53	  /// the created value. This method will be called by [`GlobalBuilder`].
 54	  ///
 55	  /// # Panics
 56	  ///
 57	  /// Panics if the given value data uses unexisted values.
 58	  pub(in crate::ir) fn new_value_data(&mut self, data: ValueData) -> Value {
 59	    let value = Value(next_global_value_id());
 60	    for v in data.kind().value_uses() {
 61	      data_mut!(self, v).used_by.insert(value);
 62	    }
 63	    self.values.borrow_mut().insert(value, data);
 64	    value
 65	  }
 66	
 67	  /// Removes the given global value by its handle. Returns the
 68	  /// corresponding value data.
 69	  ///
 70	  /// # Panics
 71	  ///
 72	  /// Panics if the given value does not exist, or the removed value is
 73	  /// currently used by other values.
 74	  pub fn remove_value(&mut self, value: Value) -> ValueData {
 75	    let data = self
 76	      .values
 77	      .borrow_mut()
 78	      .remove(&value)
 79	      .expect("`value` does not exist");
 80	    if data.kind().is_global_alloc() {
 81	      self
 82	        .inst_layout
 83	        .remove(self.inst_layout.iter().position(|v| *v == value).unwrap());
 84	    }
 85	    assert!(data.used_by.is_empty(), "`value` is used by other values");
 86	    for v in data.kind().value_uses() {
 87	      data_mut!(self, v).used_by.remove(&value);
 88	    }
 89	    data
 90	  }
 91	
 92	  /// Sets the name of the given global value.
 93	  ///
 94	  /// # Panics
 95	  ///
 96	  /// Panics if the given value does not exist,
 97	  /// or the given name (if exists) not starts with `%` or `@`.
 98	  pub fn set_value_name(&mut self, value: Value, name: Option<String>) {
 99	    self
100	      .values
101	      .borrow_mut()
102	      .get_mut(&value)
103	      .expect("`value` does not exist")
104	      .set_name(name);
105	  }
106	
107	  /// Immutably borrows the global value map.
108	  pub fn borrow_values(&self) -> Ref<HashMap<Value, ValueData>> {
109	    self.values.borrow()
110	  }
111	
112	  /// Returns a reference to the layout of all global values.
113	  pub fn inst_layout(&self) -> &[Value] {
114	    &self.inst_layout
115	  }
116	
117	  /// Immutably borrows the global value data by the given value handle.
118	  ///
119	  /// # Panics
120	  ///
121	  /// Panics if the given value does not exist.
122	  pub fn borrow_value(&self, value: Value) -> Ref<ValueData> {
123	    Ref::map(self.values.borrow(), |m| {
124	      m.get(&value).expect("`value` does not exist")
125	    })
126	  }
127	
128	  /// Creates a new function in the current program.
129	  pub fn new_func(&mut self, mut data: FunctionData) -> Function {
130	    let func = Function(next_func_id());
131	    data.dfg.globals = Rc::downgrade(&self.values);
132	    data.dfg.func_tys = Rc::downgrade(&self.func_tys);
133	    self.func_tys.borrow_mut().insert(func, data.ty.clone());
134	    self.funcs.insert(func, data);
135	    self.func_layout.push(func);
136	    func
137	  }
138	
139	  /// Removes the given function by its handle.
140	  ///
141	  /// Returns the function data if the function was previously in the program.
142	  pub fn remove_func(&mut self, func: Function) -> Option<FunctionData> {
143	    self.func_tys.borrow_mut().remove(&func);
144	    self
145	      .func_layout
146	      .remove(self.func_layout.iter().position(|f| *f == func).unwrap());
147	    self.funcs.remove(&func)
148	  }
149	
150	  /// Returns a reference to the function map.
151	  pub fn funcs(&self) -> &HashMap<Function, FunctionData> {
152	    &self.funcs
153	  }
154	
155	  /// Returns a mutable reference to the function map.
156	  pub fn funcs_mut(&mut self) -> &mut HashMap<Function, FunctionData> {
157	    &mut self.funcs
158	  }
159	
160	  /// Returns a reference to the layout of all functions.
161	  pub fn func_layout(&self) -> &[Function] {
162	    &self.func_layout
163	  }
164	
165	  /// Returns a reference to the function data by
166	  /// the given function handle.
167	  ///
168	  /// # Panics
169	  ///
170	  /// Panics if the given function does not exist.
171	  pub fn func(&self, func: Function) -> &FunctionData {
172	    self.funcs.get(&func).expect("`func` does not exist")
173	  }
174	
175	  /// Returns a mutable reference to the function data by
176	  /// the given function handle.
177	  ///
178	  /// # Panics
179	  ///
180	  /// Panics if the given function does not exist.
181	  pub fn func_mut(&mut self, func: Function) -> &mut FunctionData {
182	    self.funcs.get_mut(&func).expect("`func` does not exist")
183	  }
184	}
185	
186	/// Weak pointer for the `RefCell` of global value map.
187	///
188	/// For [`DataFlowGraph`]s in function.
189	pub(in crate::ir) type GlobalValueMapCell = Weak<RefCell<HashMap<Value, ValueData>>>;
190	
191	/// Weak pointer for the `RefCell` of function type map.
192	///
193	/// For [`DataFlowGraph`]s in function.
194	pub(in crate::ir) type FuncTypeMapCell = Weak<RefCell<HashMap<Function, Type>>>;
195	
196	/// A handle of Koopa IR function.
197	///
198	/// You can fetch [`FunctionData`] from [`Program`] by using this handle.
199	#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
200	pub struct Function(FunctionId);
201	
202	/// Data of Koopa IR function.
203	///
204	/// Functions can hold basic blocks.
205	pub struct FunctionData {
206	  ty: Type,
207	  name: String,
208	  params: Vec<Value>,
209	  dfg: DataFlowGraph,
210	  layout: Layout,
211	}
212	
213	impl FunctionData {
214	  /// Creates a new function definition.
215	  ///
216	  /// # Panics
217	  ///
218	  /// Panics if the given name not starts with `%` or `@`, or the given
219	  /// type can not construct a valid function type.
220	  pub fn new(name: String, params_ty: Vec<Type>, ret_ty: Type) -> Self {
221	    use crate::ir::values::FuncArgRef;
222	    Self::check_sanity(&name, params_ty.iter());
223	    // create function argument references
224	    let mut dfg = DataFlowGraph::new();
225	    let params = params_ty
226	      .iter()
227	      .enumerate()
228	      .map(|(i, ty)| dfg.new_value_data(FuncArgRef::new_data(i, ty.clone())))
229	      .collect();
230	    Self {
231	      ty: Type::get_function(params_ty, ret_ty),
232	      name,
233	      params,
234	      dfg,
235	      layout: Layout::new(),
236	    }
237	  }
238	
239	  /// Creates a new function definition with parameter names.
240	  ///
241	  /// # Panics
242	  ///
243	  /// Panics if the given name not starts with `%` or `@`, or the given
244	  /// type can not construct a valid function type.
245	  pub fn with_param_names(name: String, params: Vec<(Option<String>, Type)>, ret_ty: Type) -> Self {
246	    use crate::ir::values::FuncArgRef;
247	    Self::check_sanity(&name, params.iter().map(|(_, ty)| ty));
248	    // create function argument references
249	    let mut dfg = DataFlowGraph::new();
250	    let (params, params_ty) = params
251	      .into_iter()
252	      .enumerate()
253	      .map(|(i, (n, ty))| {
254	        let v = dfg.new_value_data(FuncArgRef::new_data(i, ty.clone()));
255	        dfg.set_value_name(v, n);
256	        (v, ty)
257	      })
258	      .unzip();
259	    Self {
260	      ty: Type::get_function(params_ty, ret_ty),
261	      name,
262	      params,
263	      dfg,
264	      layout: Layout::new(),
265	    }
266	  }
267	
268	  /// Creates a new function declaration.
269	  ///
270	  /// # Panics
271	  ///
272	  /// Panics if the given name not starts with `%` or `@`, or the given
273	  /// type can not construct a valid function type.
274	  pub fn new_decl(name: String, params_ty: Vec<Type>, ret_ty: Type) -> Self {
275	    Self::check_sanity(&name, params_ty.iter());
276	    Self {
277	      ty: Type::get_function(params_ty, ret_ty),
278	      name,
279	      params: Vec::new(),
280	      dfg: DataFlowGraph::new(),
281	      layout: Layout::new(),
282	    }
283	  }
284	
285	  /// Checks if the given name and type is valid.
286	  ///
287	  /// # Panics
288	  ///
289	  /// Panics if the given name and type is invalid.
290	  fn check_sanity<'a, T>(name: &str, mut params: T)
291	  where
292	    T: Iterator<Item = &'a Type>,
293	  {
294	    assert!(
295	      name.len() > 1 && (name.starts_with('%') || name.starts_with('@')),
296	      "invalid function name"
297	    );
298	    assert!(
299	      params.all(|p| !p.is_unit()),
300	      "parameter type must not be `unit`!"
301	    );
302	  }
303	
304	  /// Returns a reference to the function's type.
305	  pub fn ty(&self) -> &Type {
306	    &self.ty
307	  }
308	
309	  /// Returns a reference to the function's name.
310	  pub fn name(&self) -> &str {
311	    &self.name
312	  }
313	
314	  /// Sets the function's name.
315	  pub fn set_name(&mut self, name: String) {
316	    self.name = name;
317	  }
318	
319	  /// Returns a reference to the function parameters.
320	  pub fn params(&self) -> &[Value] {
321	    &self.params
322	  }
323	
324	  /// Returns a reference to the data flow graph.
325	  pub fn dfg(&self) -> &DataFlowGraph {
326	    &self.dfg
327	  }
328	
329	  /// Returns a mutable reference to the data flow graph.
330	  pub fn dfg_mut(&mut self) -> &mut DataFlowGraph {
331	    &mut self.dfg
332	  }
333	
334	  /// Returns a reference to the layout.
335	  pub fn layout(&self) -> &Layout {
336	    &self.layout
337	  }
338	
339	  /// Returns a mutable reference to the layout.
340	  pub fn layout_mut(&mut self) -> &mut Layout {
341	    &mut self.layout
342	  }
343	}
