345	/// A handle of Koopa IR basic block.
346	///
347	/// You can fetch [`BasicBlockData`] from [`DataFlowGraph`] in
348	/// [`FunctionData`] by using this handle.
349	#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
350	pub struct BasicBlock(pub(in crate::ir) BasicBlockId);
351	
352	/// Data of Koopa IR basic block.
353	///
354	/// `BasicBlockData` only holds parameters about this basic block, and
355	/// which values (branch/jump instructions) the current basic block is
356	/// used by. Other information, such as the data and order of instructions
357	/// in this basic block, can be found in [`FunctionData`] (in the data flow
358	/// graph or the layout).
359	pub struct BasicBlockData {
360	  name: Option<String>,
361	  params: Vec<Value>,
362	  pub(in crate::ir) used_by: HashSet<Value>,
363	}
364	
365	impl BasicBlockData {
366	  pub(in crate::ir) fn new(name: Option<String>) -> Self {
367	    Self {
368	      name,
369	      params: Vec::new(),
370	      used_by: HashSet::new(),
371	    }
372	  }
373	
374	  pub(in crate::ir) fn with_params(name: Option<String>, params: Vec<Value>) -> Self {
375	    Self {
376	      name,
377	      params,
378	      used_by: HashSet::new(),
379	    }
380	  }
381	
382	  /// Returns a reference to the basic block's name.
383	  pub fn name(&self) -> &Option<String> {
384	    &self.name
385	  }
386	
387	  /// Sets the basic block's name.
388	  pub fn set_name(&mut self, name: Option<String>) {
389	    self.name = name;
390	  }
391	
392	  /// Returns a reference to the basic block parameters.
393	  pub fn params(&self) -> &[Value] {
394	    &self.params
395	  }
396	
397	  /// Returns a mutable reference to the basic block parameters.
398	  pub fn params_mut(&mut self) -> &mut Vec<Value> {
