409	/// A handle of Koopa IR value.
410	///
411	/// You can fetch [`ValueData`] from [`DataFlowGraph`] in [`FunctionData`]
412	/// by using this handle.
413	#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
414	pub struct Value(pub(in crate::ir) ValueId);
415	
416	impl Value {
417	  /// Returns `true` if the current value handle is a global value handle.
418	  pub fn is_global(self) -> bool {
419	    is_global_id(self.0)
420	  }
