423	/// Data of Koopa IR value.
424	///
425	/// `ValueData` can hold the type and the kind of the value, and which
426	/// values the current value is used by.
427	#[derive(Debug)]
428	pub struct ValueData {
429	  ty: Type,
430	  name: Option<String>,
431	  kind: ValueKind,
432	  pub(in crate::ir) used_by: HashSet<Value>,
433	}
434	
435	impl ValueData {
436	  /// Creates a new `ValueData` with the given type and kind.
437	  pub(in crate::ir) fn new(ty: Type, kind: ValueKind) -> Self {
438	    Self {
439	      ty,
440	      name: None,
441	      kind,
442	      used_by: HashSet::new(),
443	    }
444	  }
445	
446	  /// Returns a reference to the value's type.
447	  pub fn ty(&self) -> &Type {
448	    &self.ty
449	  }
450	
451	  /// Returns a reference to the value's name.
452	  pub fn name(&self) -> &Option<String> {
453	    &self.name
454	  }
455	
456	  /// Sets the name of this value.
457	  ///
458	  /// # Panics
459	  ///
460	  /// Panics if the given name (if exists) not starts with `%` or `@`.
461	  pub(in crate::ir) fn set_name(&mut self, name: Option<String>) {
462	    assert!(
463	      name.as_ref().map_or(true, |n| n.len() > 1
464	        && (n.starts_with('%') || n.starts_with('@'))),
465	      "invalid value name"
466	    );
467	    self.name = name;
468	  }
469	
470	  /// Returns a reference to the value's kind.
471	  pub fn kind(&self) -> &ValueKind {
472	    &self.kind
473	  }
474	
475	  /// Returns a mutable reference to the value's kind.
476	  pub fn kind_mut(&mut self) -> &mut ValueKind {
477	    &mut self.kind
478	  }
479	
480	  /// Returns a reference to the values that the current value is used by.
481	  pub fn used_by(&self) -> &HashSet<Value> {
482	    &self.used_by
483	  }
484	}
485	
486	impl Clone for ValueData {
487	  /// Clones the current value data, except the `used_by` set.
488	  fn clone(&self) -> Self {
489	    Self {
490	      ty: self.ty.clone(),
491	      name: self.name.clone(),
492	      kind: self.kind.clone(),
493	      used_by: HashSet::new(),
494	    }
495	  }
496	}
497	
498	/// Kind of Koopa IR value.
499	#[derive(Clone, Debug)]
500	pub enum ValueKind {
501	  /// Integer constant.
502	  Integer(values::Integer),
503	  /// Zero initializer.
504	  ZeroInit(values::ZeroInit),
505	  /// Undefined value.
506	  Undef(values::Undef),
507	  /// Aggregate constant.
508	  Aggregate(values::Aggregate),
509	  /// Function argument reference.
510	  FuncArgRef(values::FuncArgRef),
511	  /// Basic block argument reference.
512	  BlockArgRef(values::BlockArgRef),
513	  /// Local memory allocation.
514	  Alloc(values::Alloc),
515	  /// Global memory allocation.
516	  GlobalAlloc(values::GlobalAlloc),
517	  /// Memory load.
518	  Load(values::Load),
519	  /// Memory store.
520	  Store(values::Store),
521	  /// Pointer calculation.
522	  GetPtr(values::GetPtr),
523	  /// Element pointer calculation.
524	  GetElemPtr(values::GetElemPtr),
525	  /// Binary operation.
526	  Binary(values::Binary),
527	  /// Conditional branch.
528	  Branch(values::Branch),
529	  /// Unconditional jump.
530	  Jump(values::Jump),
531	  /// Function call.
532	  Call(values::Call),
533	  /// Function return.
534	  Return(values::Return),
535	}
536	
537	impl ValueKind {
538	  /// Returns an iterator of all values that used by the `ValueKind`.
539	  pub fn value_uses(&self) -> ValueUses {
540	    ValueUses {
541	      kind: self,
542	      index: 0,
543	    }
544	  }
545	
546	  /// Returns an iterator of all basic blocks that used by the `ValueKind`.
547	  pub fn bb_uses(&self) -> BasicBlockUses {
548	    BasicBlockUses {
549	      kind: self,
550	      index: 0,
551	    }
552	  }
553	
554	  /// Returns `true` if the `ValueKind` represents a constant value.
555	  pub fn is_const(&self) -> bool {
556	    matches!(
557	      self,
558	      ValueKind::Integer(..)
559	        | ValueKind::ZeroInit(..)
560	        | ValueKind::Undef(..)
561	        | ValueKind::Aggregate(..)
562	    )
563	  }
564	
565	  /// Returns `true` if the `ValueKind` represents a global allocation.
566	  pub fn is_global_alloc(&self) -> bool {
567	    matches!(self, ValueKind::GlobalAlloc(..))
568	  }
569	
570	  /// Returns `true` if the `ValueKind` represents a local instruction.
571	  pub fn is_local_inst(&self) -> bool {
572	    matches!(
573	      self,
574	      ValueKind::Alloc(..)
575	        | ValueKind::Load(..)
576	        | ValueKind::Store(..)
577	        | ValueKind::GetPtr(..)
578	        | ValueKind::GetElemPtr(..)
579	        | ValueKind::Binary(..)
580	        | ValueKind::Branch(..)
581	        | ValueKind::Jump(..)
582	        | ValueKind::Call(..)
583	        | ValueKind::Return(..)
584	    )
585	  }
586	}
