588	/// An iterator over all values that used by a [`ValueKind`].
589	pub struct ValueUses<'a> {
590	  kind: &'a ValueKind,
591	  index: usize,
592	}
593	
594	impl<'a> Iterator for ValueUses<'a> {
595	  type Item = Value;
596	
597	  fn next(&mut self) -> Option<Self::Item> {
598	    let cur = self.index;
599	    self.index += 1;
600	    macro_rules! vec_use {
601	      ($vec:expr) => {
602	        if cur < $vec.len() {
603	          Some($vec[cur])
604	        } else {
605	          None
606	        }
607	      };
608	    }
609	    macro_rules! field_use {
610	      ($($field:expr),+) => {
611	        field_use!(@expand 0 $(,$field)+)
612	      };
613	      (@expand $index:expr) => {
614	        None
615	      };
616	      (@expand $index:expr, $head:expr $(,$tail:expr)*) => {
617	        if cur == $index {
618	          Some($head)
619	        } else {
620	          field_use!(@expand $index + 1 $(,$tail)*)
621	        }
622	      };
623	    }
624	    match self.kind {
625	      ValueKind::Aggregate(v) => vec_use!(v.elems()),
626	      ValueKind::GlobalAlloc(v) => field_use!(v.init()),
627	      ValueKind::Load(v) => field_use!(v.src()),
628	      ValueKind::Store(v) => field_use!(v.value(), v.dest()),
629	      ValueKind::GetPtr(v) => field_use!(v.src(), v.index()),
630	      ValueKind::GetElemPtr(v) => field_use!(v.src(), v.index()),
631	      ValueKind::Binary(v) => field_use!(v.lhs(), v.rhs()),
632	      ValueKind::Branch(v) => {
633	        let tlen = v.true_args().len();
634	        if cur == 0 {
635	          Some(v.cond())
636	        } else if cur >= 1 && cur <= tlen {
637	          Some(v.true_args()[cur - 1])
638	        } else if cur > tlen && cur <= tlen + v.false_args().len() {
639	          Some(v.false_args()[cur - tlen - 1])
640	        } else {
641	          None
642	        }
643	      }
644	      ValueKind::Jump(v) => vec_use!(v.args()),
645	      ValueKind::Call(v) => vec_use!(v.args()),
646	      ValueKind::Return(v) => match cur {
647	        0 => v.value(),
648	        _ => None,
649	      },
650	      _ => None,
651	    }
652	  }
653	}
