  1	//! Koopa IR builders and IR builder traits.
  2	//!
  3	//! Methods like [`Program::new_value`], [`DataFlowGraph::new_value`] or
  4	//! [`DataFlowGraph::replace_value_with`] will return an IR builder object.
  5	//! You can only create values or basic blocks by using the interface
  6	//! provided by the builder traits.
  7	
  8	use crate::ir::dfg::DataFlowGraph;
  9	use crate::ir::entities::{BasicBlock, BasicBlockData, Function, Program, Value, ValueData};
 10	use crate::ir::types::{Type, TypeKind};
 11	use crate::ir::values::*;
 12	
 13	/// A trait that provides methods for querying entity information.
 14	pub trait EntityInfoQuerier {
 15	  /// Returns the type information of the given value.
 16	  ///
 17	  /// # Panics
 18	  ///
 19	  /// Panics if the given value does not exist.
 20	  fn value_type(&self, value: Value) -> Type;
 21	
 22	  /// Checks if the given value is a constant.
 23	  ///
 24	  /// # Panics
 25	  ///
 26	  /// Panics if the given value does not exist.
 27	  fn is_const(&self, value: Value) -> bool;
 28	
 29	  /// Returns a reference to the parameters of the given basic block.
 30	  ///
 31	  /// # Panics
 32	  ///
 33	  /// Panics if the given basic block does not exist.
 34	  fn bb_params(&self, bb: BasicBlock) -> &[Value];
 35	
 36	  /// Returns the type information of the given function.
 37	  ///
 38	  /// # Panics
 39	  ///
 40	  /// Panics if the given function does not exist.
 41	  fn func_type(&self, func: Function) -> Type;
 42	}
 43	
 44	/// A builder trait that provides method for inserting value data
 45	/// to the value storage.
 46	pub trait ValueInserter {
 47	  /// Inserts the given value data to the value storage,
 48	  /// returns the handle of the inserted value.
 49	  fn insert_value(&mut self, data: ValueData) -> Value;
 50	}
 51	
 52	/// A builder trait that provides method for building value data.
 53	pub trait ValueBuilder: Sized + EntityInfoQuerier + ValueInserter {
 54	  /// Create a new value by the given value data.
 55	  fn raw(mut self, data: ValueData) -> Value {
 56	    self.insert_value(data)
 57	  }
 58	
 59	  /// Create a new integer constant.
 60	  fn integer(mut self, value: i32) -> Value {
 61	    self.insert_value(Integer::new_data(value))
 62	  }
 63	
 64	  /// Create a new zero initializer.
 65	  ///
 66	  /// # Panics
 67	  ///
 68	  /// Panics if the given type is a unit type.
 69	  fn zero_init(mut self, ty: Type) -> Value {
 70	    assert!(!ty.is_unit(), "`ty` can not be unit");
 71	    self.insert_value(ZeroInit::new_data(ty))
 72	  }
 73	
 74	  /// Create a new undefined value.
 75	  ///
 76	  /// # Panics
 77	  ///
 78	  /// Panics if the given type is a unit type.
 79	  fn undef(mut self, ty: Type) -> Value {
 80	    assert!(!ty.is_unit(), "`ty` can not be unit");
 81	    self.insert_value(Undef::new_data(ty))
 82	  }
 83	
 84	  /// Creates an aggregate constant with elements `elems`.
 85	  ///
 86	  /// # Panics
 87	  ///
 88	  /// Panics if:
 89	  ///
 90	  /// * No elements are provided.
 91	  /// * Presence of non-constant elements or unit type elements.
 92	  /// * Elements have different types.
 93	  fn aggregate(mut self, elems: Vec<Value>) -> Value {
 94	    // element list should not be empty
 95	    assert!(!elems.is_empty(), "`elems` must not be empty");
 96	    // check if all elements are constant
 97	    assert!(
 98	      elems.iter().all(|e| self.is_const(*e)),
 99	      "`elems` must all be constants"
100	    );
101	    // check if all elements have the same type
102	    assert!(
103	      elems
104	        .windows(2)
105	        .all(|e| self.value_type(e[0]) == self.value_type(e[1])),
106	      "type mismatch in `elems`"
107	    );
108	    // check base type
109	    let base = self.value_type(elems[0]);
110	    assert!(!base.is_unit(), "base type must not be `unit`");
111	    // create array type
112	    let ty = Type::get_array(base, elems.len());
113	    self.insert_value(Aggregate::new_data(elems, ty))
114	  }
115	}
116	
117	/// A builder for building and inserting global instructions.
118	pub trait GlobalInstBuilder: ValueBuilder {
119	  /// Creates a global memory allocation.
120	  ///
121	  /// # Panics
122	  ///
123	  /// Panics if the type of the initialize is a unit type.
124	  fn global_alloc(mut self, init: Value) -> Value {
125	    let init_ty = self.value_type(init);
126	    assert!(!init_ty.is_unit(), "the type of `init` must not be unit");
127	    let ty = Type::get_pointer(init_ty);
128	    self.insert_value(GlobalAlloc::new_data(init, ty))
129	  }
130	}
131	
132	/// A builder for building and inserting local instructions.
133	pub trait LocalInstBuilder: ValueBuilder {
134	  /// Creates a local memory allocation.
135	  ///
136	  /// # Panics
137	  ///
138	  /// Panics if the given type is a unit type.
139	  fn alloc(mut self, ty: Type) -> Value {
140	    assert!(!ty.is_unit(), "`ty` can not be unit");
141	    self.insert_value(Alloc::new_data(Type::get_pointer(ty)))
142	  }
143	
144	  /// Creates a memory load with the given source.
145	  ///
146	  /// # Panics
147	  ///
148	  /// Panics if the type of the source value is not a pointer type.
149	  fn load(mut self, src: Value) -> Value {
150	    let src_ty = self.value_type(src);
151	    let ty = match src_ty.kind() {
152	      TypeKind::Pointer(ty) => ty.clone(),
153	      _ => panic!("expected a pointer type"),
154	    };
155	    self.insert_value(Load::new_data(src, ty))
156	  }
157	
158	  /// Creates a memory store with the given value and destination.
159	  ///
160	  /// # Panics
161	  ///
162	  /// Panics if the dest type is not a pointer of the value type.
163	  fn store(mut self, value: Value, dest: Value) -> Value {
164	    assert!(
165	      Type::get_pointer(self.value_type(value)) == self.value_type(dest),
166	      "the type of `dest` must be the pointer of `value`'s type"
167	    );
168	    self.insert_value(Store::new_data(value, dest))
169	  }
170	
171	  /// Creates a pointer calculation with the given source pointer and index.
172	  ///
173	  /// # Panics
174	  ///
175	  /// Panics if the source type is not a pointer type, or the index type is
176	  /// not an integer type.
177	  fn get_ptr(mut self, src: Value, index: Value) -> Value {
178	    let src_ty = self.value_type(src);
179	    assert!(
180	      matches!(src_ty.kind(), TypeKind::Pointer(..)),
181	      "`src` must be a pointer"
182	    );
183	    assert!(
184	      self.value_type(index).is_i32(),
185	      "`index` must be an integer"
186	    );
187	    self.insert_value(GetPtr::new_data(src, index, src_ty))
188	  }
189	
190	  /// Creates a element pointer calculation with the given source pointer
191	  /// and index.
192	  ///
193	  /// # Panics
194	  ///
195	  /// Panics if the source type is not a pointer type of an array, or the
196	  /// index type is not an integer type.
197	  fn get_elem_ptr(mut self, src: Value, index: Value) -> Value {
198	    assert!(
199	      self.value_type(index).is_i32(),
200	      "`index` must be an integer"
201	    );
202	    let ty = match self.value_type(src).kind() {
203	      TypeKind::Pointer(ty) => match ty.kind() {
204	        TypeKind::Array(base, _) => Type::get_pointer(base.clone()),
205	        _ => panic!("`src` must be a pointer of array"),
206	      },
207	      _ => panic!("`src` must be a pointer of array"),
208	    };
209	    self.insert_value(GetElemPtr::new_data(src, index, ty))
210	  }
211	
212	  /// Creates a binary operation.
213	  ///
214	  /// # Panics
215	  ///
216	  /// Panics if the lhs/rhs type is not an integer type.
217	  fn binary(mut self, op: BinaryOp, lhs: Value, rhs: Value) -> Value {
218	    let lhs_ty = self.value_type(lhs);
219	    let rhs_ty = self.value_type(rhs);
220	    assert!(
221	      lhs_ty.is_i32() && lhs_ty == rhs_ty,
222	      "both `lhs` and `rhs` must be integer"
223	    );
224	    self.insert_value(Binary::new_data(op, lhs, rhs, lhs_ty))
225	  }
226	
227	  /// Creates a conditional branch with the given condition and targets.
228	  ///
229	  /// # Panics
230	  ///
231	  /// Panics if the condition type is not an integer type, or the true/false
232	  /// basic block has parameters.
233	  fn branch(mut self, cond: Value, true_bb: BasicBlock, false_bb: BasicBlock) -> Value {
234	    assert!(self.value_type(cond).is_i32(), "`cond` must be integer");
235	    assert!(
236	      self.bb_params(true_bb).is_empty(),
237	      "`true_bb` must not have parameters"
238	    );
239	    assert!(
240	      self.bb_params(false_bb).is_empty(),
241	      "`false_bb` must not have parameters"
242	    );
243	    self.insert_value(Branch::new_data(cond, true_bb, false_bb))
244	  }
245	
246	  /// Creates a conditional branch with the given condition, targets
247	  /// and arguments.
248	  ///
249	  /// # Panics
250	  ///
251	  /// Panics if the condition type is not an integer type, or the argument
252	  /// types of the true/false basic block do not match.
253	  fn branch_with_args(
254	    mut self,
255	    cond: Value,
256	    true_bb: BasicBlock,
257	    false_bb: BasicBlock,
258	    true_args: Vec<Value>,
259	    false_args: Vec<Value>,
260	  ) -> Value {
261	    assert!(self.value_type(cond).is_i32(), "`cond` must be integer");
262	    check_bb_arg_types(&self, self.bb_params(true_bb), &true_args);
263	    check_bb_arg_types(&self, self.bb_params(false_bb), &false_args);
264	    self.insert_value(Branch::with_args(
265	      cond, true_bb, false_bb, true_args, false_args,
266	    ))
267	  }
268	
269	  /// Creates a unconditional jump with the given target.
270	  ///
271	  /// # Panics
272	  ///
273	  /// Panics if the target basic block has parameters.
274	  fn jump(mut self, target: BasicBlock) -> Value {
275	    assert!(
276	      self.bb_params(target).is_empty(),
277	      "`target` must not have parameters"
278	    );
279	    self.insert_value(Jump::new_data(target))
280	  }
281	
282	  /// Creates a unconditional jump with the given target and arguments.
283	  ///
284	  /// # Panics
285	  ///
286	  /// Panics if the argument types of the target basic block do not match.
287	  fn jump_with_args(mut self, target: BasicBlock, args: Vec<Value>) -> Value {
288	    check_bb_arg_types(&self, self.bb_params(target), &args);
289	    self.insert_value(Jump::with_args(target, args))
290	  }
291	
292	  /// Creates a function call.
293	  ///
294	  /// # Panics
295	  ///
296	  /// Panics if the argument types of the callee do not match.
297	  fn call(mut self, callee: Function, args: Vec<Value>) -> Value {
298	    let ty = match self.func_type(callee).kind() {
299	      TypeKind::Function(params, ret) => {
300	        assert!(
301	          params
302	            .iter()
303	            .zip(args.iter())
304	            .all(|(ty, a)| ty == &self.value_type(*a)),
305	          "argument type mismatch"
306	        );
307	        ret.clone()
308	      }
309	      _ => panic!("expected a function type"),
310	    };
311	    self.insert_value(Call::new_data(callee, args, ty))
312	  }
313	
314	  /// Creates a new return instruction.
315	  ///
316	  /// # Panics
317	  ///
318	  /// Panics if the value type (if value is not `None`) is a unit type.
319	  fn ret(mut self, value: Option<Value>) -> Value {
320	    assert!(
321	      value.map_or(true, |v| !self.value_type(v).is_unit()),
322	      "the type of `value` must not be `unit`"
323	    );
324	    self.insert_value(Return::new_data(value))
325	  }
326	}
327	
328	/// A builder trait that provides method for building value data and
329	/// inserting value data to the value storage.
330	pub trait BasicBlockBuilder: Sized + ValueInserter {
331	  /// Inserts the given basic block data to the basic block storage,
332	  /// returns the handle of the inserted basic block.
333	  fn insert_bb(&mut self, data: BasicBlockData) -> BasicBlock;
334	
335	  /// Creates a new basic block with the given name.
336	  ///
337	  /// # Panics
338	  ///
339	  /// Panics if the given name (if exists) not starts with `%` or `@`.
340	  fn basic_block(mut self, name: Option<String>) -> BasicBlock {
341	    check_bb_name(&name);
342	    self.insert_bb(BasicBlockData::new(name))
343	  }
344	
345	  /// Creates a new basic block with the given name and parameter types.
346	  ///
347	  /// # Panics
348	  ///
349	  /// Panics if there are unit types in the given parameter types.
350	  fn basic_block_with_params(mut self, name: Option<String>, params_ty: Vec<Type>) -> BasicBlock {
351	    check_bb_name(&name);
352	    assert!(
353	      params_ty.iter().all(|p| !p.is_unit()),
354	      "parameter type must not be `unit`!"
355	    );
356	    let params = params_ty
357	      .iter()
358	      .enumerate()
359	      .map(|(i, ty)| self.insert_value(BlockArgRef::new_data(i, ty.clone())))
360	      .collect();
361	    self.insert_bb(BasicBlockData::with_params(name, params))
362	  }
363	
364	  /// Creates a new basic block with the given name, parameter names
365	  /// and parameter types.
366	  ///
367	  /// # Panics
368	  ///
369	  /// Panics if there are unit types in the given parameter types.
370	  fn basic_block_with_param_names(
371	    mut self,
372	    name: Option<String>,
373	    params: Vec<(Option<String>, Type)>,
374	  ) -> BasicBlock {
375	    check_bb_name(&name);
376	    assert!(
377	      params.iter().all(|(_, p)| !p.is_unit()),
378	      "parameter type must not be `unit`!"
379	    );
380	    let params = params
381	      .into_iter()
382	      .enumerate()
383	      .map(|(i, (n, ty))| {
384	        let mut arg = BlockArgRef::new_data(i, ty);
385	        arg.set_name(n);
386	        self.insert_value(arg)
387	      })
388	      .collect();
389	    self.insert_bb(BasicBlockData::with_params(name, params))
390	  }
391	}
392	
393	/// Checks if the parameter types of the given basic block type matches
394	/// the given argument types.
395	///
396	/// # Panics
397	///
398	/// Panics if the parameter types of the given basic block type does not
399	/// match the given argument types.
400	fn check_bb_arg_types(querier: &impl EntityInfoQuerier, params: &[Value], args: &[Value]) {
401	  assert!(
402	    params.len() == args.len()
403	      && params
404	        .iter()
405	        .zip(args.iter())
406	        .all(|(p, a)| querier.value_type(*p) == querier.value_type(*a)),
407	    "arguments type of basic block mismatch"
408	  );
409	}
410	
411	/// Checks if the given name is a valid basic block name.
412	///
413	/// # Panics
414	///
415	/// Panics if the given name (if exists) not starts with `%` or `@`.
416	fn check_bb_name(name: &Option<String>) {
417	  assert!(
418	    name.as_ref().map_or(true, |n| n.len() > 1
419	      && (n.starts_with('%') || n.starts_with('@'))),
420	    "invalid basic block name"
421	  );
422	}
423	
424	/// An entity information querier based on data flow graph.
425	pub trait DfgBasedInfoQuerier {
426	  fn dfg(&self) -> &DataFlowGraph;
427	}
428	
429	impl<T: DfgBasedInfoQuerier> EntityInfoQuerier for T {
430	  fn value_type(&self, value: Value) -> Type {
431	    self
432	      .dfg()
433	      .globals
434	      .upgrade()
435	      .unwrap()
436	      .borrow()
437	      .get(&value)
438	      .or_else(|| self.dfg().values().get(&value))
439	      .expect("value does not exist")
440	      .ty()
441	      .clone()
442	  }
443	
444	  fn is_const(&self, value: Value) -> bool {
445	    self
446	      .dfg()
447	      .globals
448	      .upgrade()
449	      .unwrap()
450	      .borrow()
451	      .get(&value)
452	      .or_else(|| self.dfg().values().get(&value))
453	      .expect("value does not exist")
454	      .kind()
455	      .is_const()
456	  }
457	
458	  fn bb_params(&self, bb: BasicBlock) -> &[Value] {
459	    self
460	      .dfg()
461	      .bbs()
462	      .get(&bb)
463	      .expect("basic block does not exist")
464	      .params()
465	  }
466	
467	  fn func_type(&self, func: Function) -> Type {
468	    self
469	      .dfg()
470	      .func_tys
471	      .upgrade()
472	      .unwrap()
473	      .borrow()
474	      .get(&func)
475	      .expect("function does not exist")
476	      .clone()
477	  }
478	}
479	
480	/// An value builder that builds a new local value and inserts it
481	/// to the data flow graph.
482	///
483	/// Returned by method [`DataFlowGraph::new_value`].
484	pub struct LocalBuilder<'a> {
485	  pub(in crate::ir) dfg: &'a mut DataFlowGraph,
486	}
487	
488	impl<'a> DfgBasedInfoQuerier for LocalBuilder<'a> {
489	  fn dfg(&self) -> &DataFlowGraph {
490	    self.dfg
491	  }
492	}
493	
494	impl<'a> ValueInserter for LocalBuilder<'a> {
495	  fn insert_value(&mut self, data: ValueData) -> Value {
496	    self.dfg.new_value_data(data)
497	  }
498	}
499	
500	impl<'a> ValueBuilder for LocalBuilder<'a> {}
501	impl<'a> LocalInstBuilder for LocalBuilder<'a> {}
502	
503	/// An basic block builder that builds a new basic block and inserts it
504	/// to the data flow graph.
505	///
506	/// Returned by method [`DataFlowGraph::new_bb`].
507	pub struct BlockBuilder<'a> {
508	  pub(in crate::ir) dfg: &'a mut DataFlowGraph,
509	}
510	
511	impl<'a> ValueInserter for BlockBuilder<'a> {
512	  fn insert_value(&mut self, data: ValueData) -> Value {
513	    self.dfg.new_value_data(data)
514	  }
515	}
516	
517	impl<'a> BasicBlockBuilder for BlockBuilder<'a> {
518	  fn insert_bb(&mut self, data: BasicBlockData) -> BasicBlock {
519	    self.dfg.new_bb_data(data)
520	  }
521	}
522	
523	/// An value builder that replaces an existing local value.
524	/// The inserted new value will have the same value handle as the old one.
525	///
526	/// Returned by method [`DataFlowGraph::replace_value_with`].
527	pub struct ReplaceBuilder<'a> {
528	  pub(in crate::ir) dfg: &'a mut DataFlowGraph,
529	  pub(in crate::ir) value: Value,
530	}
531	
532	impl<'a> DfgBasedInfoQuerier for ReplaceBuilder<'a> {
533	  fn dfg(&self) -> &DataFlowGraph {
534	    self.dfg
535	  }
536	}
537	
538	impl<'a> ValueInserter for ReplaceBuilder<'a> {
539	  fn insert_value(&mut self, data: ValueData) -> Value {
540	    self.dfg.replace_value_with_data(self.value, data);
541	    self.value
542	  }
543	}
544	
545	impl<'a> ValueBuilder for ReplaceBuilder<'a> {}
546	impl<'a> LocalInstBuilder for ReplaceBuilder<'a> {}
547	
548	/// An value builder that builds a new global value and inserts it
549	/// to the program.
550	///
