    11	/// `DataFlowGraph` holds all data of values ([`ValueData`]) and basic
    12	/// blocks ([`BasicBlockData`]), and maintains their use-define and
    13	/// define-use chain.
    14	pub struct DataFlowGraph {
    15	  pub(in crate::ir) globals: GlobalValueMapCell,
    16	  pub(in crate::ir) func_tys: FuncTypeMapCell,
    17	  values: HashMap<Value, ValueData>,
    18	  bbs: HashMap<BasicBlock, BasicBlockData>,
    19	}
    20	
    21	/// Returns a reference to the value data by the given value handle.
    22	macro_rules! data {
    23	  ($self:ident, $value:expr) => {
    24	    $self
    25	      .globals
    26	      .upgrade()
    27	      .unwrap()
    28	      .borrow()
    29	      .get(&$value)
    30	      .or_else(|| $self.values.get(&$value))
    31	      .expect("value does not exist")
    32	  };
    33	}
    34	
    35	/// Returns a mutable reference to the value data by the given value handle.
    36	macro_rules! data_mut {
    37	  ($self:ident, $value:expr) => {
    38	    $self
    39	      .globals
    40	      .upgrade()
    41	      .unwrap()
    42	      .borrow_mut()
    43	      .get_mut(&$value)
    44	      .or_else(|| $self.values.get_mut(&$value))
    45	      .expect("value does not exist")
    46	  };
    47	}
