    49	impl DataFlowGraph {
    50	  /// Creates a new data flow graph.
    51	  pub(in crate::ir) fn new() -> Self {
    52	    Self {
    53	      globals: GlobalValueMapCell::new(),
    54	      func_tys: FuncTypeMapCell::new(),
    55	      values: HashMap::new(),
    56	      bbs: HashMap::new(),
    57	    }
    58	  }
    59	
    60	  /// Creates a new value in the current data flow graph.
    61	  /// Returns a [`LocalBuilder`] for building the new local value.
    62	  pub fn new_value(&mut self) -> LocalBuilder {
    63	    LocalBuilder { dfg: self }
    64	  }
    65	
    66	  /// Creates a new local value by its value data. Returns the handle of
    67	  /// the created value. This method will be called by [`LocalBuilder`].
    68	  ///
    69	  /// # Panics
    70	  ///
    71	  /// Panics if the given value data uses unexisted values or basic blocks.
    72	  pub(in crate::ir) fn new_value_data(&mut self, data: ValueData) -> Value {
    73	    let value = Value(next_local_value_id());
    74	    for v in data.kind().value_uses() {
    75	      data_mut!(self, v).used_by.insert(value);
    76	    }
    77	    for bb in data.kind().bb_uses() {
    78	      self.bb_mut(bb).used_by.insert(value);
    79	    }
    80	    self.values.insert(value, data);
    81	    value
    82	  }
    83	
    84	  /// Replaces the given value with a new value.
    85	  /// Returns a [`ReplaceBuilder`] for building the new value.
    86	  ///
    87	  /// # Panics
    88	  ///
    89	  /// Panics if the given value does not exist.
    90	  pub fn replace_value_with(&mut self, value: Value) -> ReplaceBuilder {
    91	    ReplaceBuilder { dfg: self, value }
    92	  }
    93	
    94	  /// Replaces the given value with a new value data.
    95	  /// This method will be called by [`ReplaceBuilder`].
    96	  ///
    97	  /// # Panics
    98	  ///
    99	  /// Panics if the given value does not exist.
   100	  pub(in crate::ir) fn replace_value_with_data(&mut self, value: Value, data: ValueData) {
   101	    let old = self.values.remove(&value).unwrap();
   102	    for v in old.kind().value_uses() {
   103	      data_mut!(self, v).used_by.remove(&value);
   104	    }
   105	    for bb in old.kind().bb_uses() {
   106	      self.bb_mut(bb).used_by.remove(&value);
   107	    }
   108	    for v in data.kind().value_uses() {
   109	      data_mut!(self, v).used_by.insert(value);
   110	    }
   111	    for bb in data.kind().bb_uses() {
   112	      self.bb_mut(bb).used_by.insert(value);
   113	    }
   114	    self.values.insert(value, data);
   115	  }
   116	
   117	  /// Removes the given value. Returns the corresponding value data.
   118	  ///
   119	  /// # Panics
   120	  ///
   121	  /// Panics if the given value does not exist, or the removed value is
   122	  /// currently used by other values.
   123	  pub fn remove_value(&mut self, value: Value) -> ValueData {
   124	    let data = self.values.remove(&value).expect("`value` does not exist");
   125	    assert!(data.used_by.is_empty(), "`value` is used by other values");
   126	    for v in data.kind().value_uses() {
   127	      data_mut!(self, v).used_by.remove(&value);
   128	    }
   129	    for bb in data.kind().bb_uses() {
   130	      self.bb_mut(bb).used_by.remove(&value);
   131	    }
   132	    data
   133	  }
   134	
   135	  /// Sets the name of the given value.
   136	  ///
   137	  /// # Panics
   138	  ///
   139	  /// Panics if the given value does not exist,
   140	  /// or the given name (if exists) not starts with `%` or `@`.
   141	  pub fn set_value_name(&mut self, value: Value, name: Option<String>) {
   142	    self
   143	      .values
   144	      .get_mut(&value)
   145	      .expect("`value` does not exist")
   146	      .set_name(name);
   147	  }
