   149	  /// Returns a reference to the given local value.
   150	  ///
   151	  /// # Panics
   152	  ///
   153	  /// Panics if the given local value does not exist.
   154	  pub fn value(&self, value: Value) -> &ValueData {
   155	    self.values.get(&value).expect("`value` does not exist")
   156	  }
   157	
   158	  /// Returns a reference to the value map.
   159	  pub fn values(&self) -> &HashMap<Value, ValueData> {
   160	    &self.values
   161	  }
