   163	  /// Checks if the two given values are equal.
   164	  pub fn value_eq(&self, lhs: Value, rhs: Value) -> bool {
   165	    self.data_eq(data!(self, lhs), data!(self, rhs))
   166	  }
   167	
   168	  /// Checks if the two given value data are equal.
   169	  pub fn data_eq(&self, lhs: &ValueData, rhs: &ValueData) -> bool {
   170	    use crate::ir::entities::ValueKind::*;
   171	    macro_rules! return_if {
   172	      ($e:expr) => {
   173	        if $e {
   174	          return false;
   175	        }
   176	      };
   177	    }
   178	    return_if!(lhs.ty() != rhs.ty());
   179	    match (lhs.kind(), rhs.kind()) {
   180	      (Integer(l), Integer(r)) => return_if!(l.value() != r.value()),
   181	      (ZeroInit(_), ZeroInit(_)) => return true,
   182	      (Undef(_), Undef(_)) => return true,
   183	      (Aggregate(l), Aggregate(r)) => return_if!(l.elems().len() != r.elems().len()),
   184	      (FuncArgRef(l), FuncArgRef(r)) => return_if!(l.index() != r.index()),
   185	      (BlockArgRef(l), BlockArgRef(r)) => return_if!(l.index() != r.index()),
   186	      (Alloc(_), Alloc(_)) => return true,
   187	      (GlobalAlloc(_), GlobalAlloc(_)) => (),
   188	      (Load(_), Load(_)) => (),
   189	      (Store(_), Store(_)) => (),
   190	      (GetPtr(_), GetPtr(_)) => (),
   191	      (GetElemPtr(_), GetElemPtr(_)) => (),
   192	      (Binary(l), Binary(r)) => return_if!(l.op() != r.op()),
   193	      (Branch(l), Branch(r)) => {
   194	        return_if!(
   195	          l.true_bb() != r.true_bb()
   196	            || l.false_bb() != r.false_bb()
   197	            || l.true_args().len() != r.true_args().len()
   198	            || l.false_args().len() != r.false_args().len()
   199	        )
   200	      }
   201	      (Jump(l), Jump(r)) => {
   202	        return_if!(l.target() != r.target() || l.args().len() != r.args().len())
   203	      }
   204	      (Call(l), Call(r)) => {
   205	        return_if!(l.callee() != r.callee() || l.args().len() != r.args().len())
   206	      }
   207	      (Return(l), Return(r)) => return_if!(l.value().xor(r.value()).is_some()),
   208	      _ => return false,
   209	    }
   210	    for (lu, ru) in lhs.kind().value_uses().zip(rhs.kind().value_uses()) {
   211	      return_if!(!self.value_eq(lu, ru));
   212	    }
   213	    true
   214	  }
