   230	  /// Removes the given basic block, also removes all basic block
   231	  /// parameters. Returns the corresponding basic block data.
   232	  ///
   233	  /// # Panics
   234	  ///
   235	  /// Panics if:
   236	  ///
   237	  /// * the given basic block does not exist, or
   238	  /// * the removed basic block is currently used by other values, or
   239	  /// * the parameters of the removed basic block do not exist, or
   240	  ///   are currently used by other values.
   241	  pub fn remove_bb(&mut self, bb: BasicBlock) -> BasicBlockData {
   242	    let data = self.bbs.remove(&bb).expect("`bb` does not exist");
   243	    assert!(data.used_by.is_empty(), "`bb` is used by other values");
   244	    for p in data.params() {
   245	      let param = self
   246	        .values
   247	        .remove(p)
   248	        .expect("basic block parameter does not exist");
   249	      assert!(
   250	        param.used_by.is_empty(),
   251	        "basic block parameter is used by other values"
   252	      );
   253	    }
   254	    data
   255	  }
