    66	  /// Creates a new local value by its value data. Returns the handle of
    67	  /// the created value. This method will be called by [`LocalBuilder`].
    68	  ///
    69	  /// # Panics
    70	  ///
    71	  /// Panics if the given value data uses unexisted values or basic blocks.
    72	  pub(in crate::ir) fn new_value_data(&mut self, data: ValueData) -> Value {
    73	    let value = Value(next_local_value_id());
    74	    for v in data.kind().value_uses() {
    75	      data_mut!(self, v).used_by.insert(value);
    76	    }
    77	    for bb in data.kind().bb_uses() {
    78	      self.bb_mut(bb).used_by.insert(value);
    79	    }
