   117	  /// Removes the given value. Returns the corresponding value data.
   118	  ///
   119	  /// # Panics
   120	  ///
   121	  /// Panics if the given value does not exist, or the removed value is
   122	  /// currently used by other values.
   123	  pub fn remove_value(&mut self, value: Value) -> ValueData {
   124	    let data = self.values.remove(&value).expect("`value` does not exist");
   125	    assert!(data.used_by.is_empty(), "`value` is used by other values");
   126	    for v in data.kind().value_uses() {
   127	      data_mut!(self, v).used_by.remove(&value);
   128	    }
   129	    for bb in data.kind().bb_uses() {
   130	      self.bb_mut(bb).used_by.remove(&value);
   131	    }
   132	    data
   133	  }
