   140	  /// or the given name (if exists) not starts with `%` or `@`.
   141	  pub fn set_value_name(&mut self, value: Value, name: Option<String>) {
   142	    self
   143	      .values
   144	      .get_mut(&value)
   145	      .expect("`value` does not exist")
