    17	fn try_main() -> result::Result<i32, MainError> {
    18	  // parse command line arguments
    19	  let CommandLineArgs { input, libs } = parse_cmd_args()?;
    20	  // parse the input file
    21	  let program = if let Some(file) = input {
    22	    Driver::from_path(file)
    23	      .map_err(MainError::InvalidFile)?
    24	      .generate_program()
    25	  } else {
    26	    Driver::from(stdin()).generate_program()
    27	  }
    28	  .map_err(|_| MainError::ParseError)?;
    29	  // interpret the program
    30	  let interpreter = Interpreter::new(libs);
    31	  Generator::with_visitor(sink(), interpreter)
    32	    .generate_on(&program)
    33	    .map_err(MainError::OtherError)
    34	}
